using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their impact on civilization." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor", Bio = "Specializes in algorithms and programming language theory with over 15 years of teaching experience.", Email = "lovelace@university.edu" },
            new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor", Bio = "Researches computational theory and artificial intelligence. Published over 40 peer-reviewed papers.", Email = "turing@university.edu" },
            new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Expert in abstract algebra and theoretical physics. Recipient of the Distinguished Teaching Award.", Email = "noether@university.edu" },
            new() { Id = 4, Name = "Dr. William Shakespeare", Title = "Professor", Bio = "Specializes in early modern literature and creative writing. Author of several acclaimed textbooks.", Email = "shakespeare@university.edu" },
            new() { Id = 5, Name = "Dr. Marie Curie", Title = "Professor", Bio = "Researches nuclear physics and radiochemistry. Fellow of the National Academy of Sciences.", Email = "curie@university.edu" },
            new() { Id = 6, Name = "Dr. Herodotus Grant", Title = "Associate Professor", Bio = "Focuses on ancient civilizations and historiography. Leads the university's archaeology program.", Email = "grant@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques. Prerequisites: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 2, IsFeatured = true, MaxEnrollment = 80 },
            new() { Id = 3, Code = "CS 301", Title = "Operating Systems", Description = "Principles of operating system design including process management, memory management, file systems, and concurrency.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Hall 110", DepartmentId = 1, InstructorId = 2, IsFeatured = false, MaxEnrollment = 60 },
            new() { Id = 4, Code = "CS 350", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search, knowledge representation, machine learning, and natural language processing.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 2, IsFeatured = true, MaxEnrollment = 70 },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 100", DepartmentId = 2, InstructorId = 3, IsFeatured = true, MaxEnrollment = 150 },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Building 204", DepartmentId = 2, InstructorId = 3, IsFeatured = false, MaxEnrollment = 90 },
            new() { Id = 7, Code = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, fields, and their applications in modern mathematics and cryptography.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Location = "Math Building 310", DepartmentId = 2, InstructorId = 3, IsFeatured = false, MaxEnrollment = 40 },
            new() { Id = 8, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop essential academic writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities 102", DepartmentId = 3, InstructorId = 4, IsFeatured = false, MaxEnrollment = 30 },
            new() { Id = 9, Code = "ENG 250", Title = "World Literature", Description = "Survey of major literary works from diverse cultures and time periods. Focus on critical analysis and interpretation.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities 205", DepartmentId = 3, InstructorId = 4, IsFeatured = true, MaxEnrollment = 35 },
            new() { Id = 10, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Physics Lab 101", DepartmentId = 4, InstructorId = 5, IsFeatured = false, MaxEnrollment = 100 },
            new() { Id = 11, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, circuits, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Physics Lab 203", DepartmentId = 4, InstructorId = 5, IsFeatured = true, MaxEnrollment = 60 },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from prehistory through the late medieval period.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Liberal Arts 300", DepartmentId = 5, InstructorId = 6, IsFeatured = false, MaxEnrollment = 80 },
            new() { Id = 13, Code = "HIST 250", Title = "Modern World History", Description = "Examines global developments from the Age of Exploration to the present day, including revolutions, world wars, and globalization.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Location = "Liberal Arts 112", DepartmentId = 5, InstructorId = 6, IsFeatured = false, MaxEnrollment = 80 },
        };

        // Wire up navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null, int? credits = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (credits.HasValue)
            query = query.Where(c => c.Credits == credits.Value);

        return query.OrderBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<int> GetDistinctCredits() => _courses.Select(c => c.Credits).Distinct().OrderBy(c => c).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

